using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class HospitalBillboardProbe{static HospitalBillboardProbe(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("HospitalBillboardProbe.request"))return;File.Delete("HospitalBillboardProbe.request");var s=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var all=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshFilter>(true)).Where(f=>f.name=="billboard (8)").ToArray();File.WriteAllLines("FinalEnvironmentRoadReview/HospitalBillboardProbe.txt",new[]{"Selected="+(Selection.activeGameObject?Selection.activeGameObject.name:"none")}.Concat(all.Select(f=>f.name+" center="+f.GetComponent<Renderer>().bounds+" position="+f.transform.position+" rotation="+f.transform.eulerAngles+" mesh="+AssetDatabase.GetAssetPath(f.sharedMesh))));}}

